ALTER TABLE issues_receipts ADD COLUMN project_id TEXT;
UPDATE issues_receipts SET project_id=(SELECT project_id FROM issues_issues WHERE workspace_id=issues_receipts.workspace_id AND id=result_id);
ALTER TABLE issues_events ADD COLUMN project_id TEXT;
UPDATE issues_events SET project_id=(SELECT project_id FROM issues_issues WHERE workspace_id=issues_events.workspace_id AND id=aggregate_id);
CREATE TABLE issues_frozen_scopes (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging','purged')), PRIMARY KEY(workspace_id,project_id));
CREATE TABLE issues_purge_bypass (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, PRIMARY KEY(workspace_id,project_id));
CREATE TRIGGER issues_freeze_comments_insert BEFORE INSERT ON issues_comments WHEN EXISTS(SELECT 1 FROM issues_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=(SELECT project_id FROM issues_issues WHERE workspace_id=NEW.workspace_id AND id=NEW.issue_id))) AND NOT EXISTS(SELECT 1 FROM issues_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=(SELECT project_id FROM issues_issues WHERE workspace_id=NEW.workspace_id AND id=NEW.issue_id))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER issues_freeze_comments_update BEFORE UPDATE ON issues_comments WHEN (EXISTS(SELECT 1 FROM issues_frozen_scopes f WHERE f.workspace_id=NEW.workspace_id AND (f.project_id='' OR f.project_id=(SELECT project_id FROM issues_issues WHERE workspace_id=NEW.workspace_id AND id=NEW.issue_id))) AND NOT EXISTS(SELECT 1 FROM issues_purge_bypass b WHERE b.workspace_id=NEW.workspace_id AND (b.project_id='' OR b.project_id=(SELECT project_id FROM issues_issues WHERE workspace_id=NEW.workspace_id AND id=NEW.issue_id)))) OR (EXISTS(SELECT 1 FROM issues_frozen_scopes f WHERE f.workspace_id=OLD.workspace_id AND (f.project_id='' OR f.project_id=(SELECT project_id FROM issues_issues WHERE workspace_id=OLD.workspace_id AND id=OLD.issue_id))) AND NOT EXISTS(SELECT 1 FROM issues_purge_bypass b WHERE b.workspace_id=OLD.workspace_id AND (b.project_id='' OR b.project_id=(SELECT project_id FROM issues_issues WHERE workspace_id=OLD.workspace_id AND id=OLD.issue_id)))) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
